window.docContents[6].resolve({"/References/#Type-Systems--References___-Typing-Mutable-References--Properties--Preservation___-Finally--Preservation___":{"contents":"Now that we've got everything set up right, the proof of\npreservation is actually quite straightforward:\n\ntheorem preservation {δ : StoreTy} {t t' : Tm} {τ : Ty} {ρ ρ' : Store}\n  (hTy : <{ ∅ / δ ⊢ t ⦂ τ }>)\n  (hStoreTy : δ ⊢ ρ)\n  (hEval : t / ρ ⟶ t' / ρ') :\n    ∃ δ', Extends δ' δ ∧ (<{ ∅ / δ' ⊢ t' ⦂ τ }>) ∧ (δ' ⊢ ρ') := by\n\n    generalize heq : (∅ : Context) = Γ at hTy\n    -- discharge the goals where `t` doesn't step\n    induction hTy generalizing t' with (subst_vars; try (inversion hEval; done))\n    | app h₁ h₂ ih₁ ih₂ =>\n      inversion hEval with\n      | appAbs =>\n        inversion h₁ with | abs h =>\n        exists δ; constructor\n        apply extends_refl; constructor\n        apply_rules [substitution_preserves_typing, extends_refl] using StlcRefTyping\n        assumption\n      | app₁ hs =>\n        have ⟨δ', hExt, hTy', hStoreTy'⟩ := ih₁ hs rfl\n        exists δ'; constructor\n        assumption; constructor\n        solve_by_elim [store_weakening] using StlcRefTyping\n        assumption\n      | app₂ _ hs =>\n        have ⟨δ', hExt, hTy', hStoreTy'⟩ := ih₂ hs rfl\n        exists δ'; constructor\n        assumption; constructor\n        solve_by_elim [store_weakening] using StlcRefTyping\n        assumption\n    | succ _ ih =>\n      inversion hEval with\n      | succNat =>\n        exists δ; constructor\n        apply extends_refl; constructor\n        constructor\n        assumption\n      | succ hs =>\n        have ⟨δ', hExt, hTy', hStoreTy'⟩ := ih hs rfl\n        exists δ'; constructor\n        assumption; constructor\n        solve_by_elim [store_weakening] using StlcRefTyping\n        assumption\n    | pred _ ih =>\n      inversion hEval with\n      | predConst =>\n        exists δ; constructor\n        apply extends_refl; constructor\n        constructor\n        assumption\n      | pred hs =>\n        have ⟨δ', hExt, hTy', hStoreTy'⟩ := ih hs rfl\n        exists δ'; constructor\n        assumption; constructor\n        solve_by_elim [store_weakening] using StlcRefTyping\n        assumption\n    | mult h₁ h₂ ih₁ ih₂ =>\n      inversion hEval with\n      | multConst =>\n        exists δ; constructor\n        apply extends_refl; constructor\n        constructor\n        assumption\n      | mult₁ hs =>\n        have ⟨δ', hExt, hTy', hStoreTy'⟩ := ih₁ hs rfl\n        exists δ'; constructor\n        assumption; constructor\n        solve_by_elim [store_weakening] using StlcRefTyping\n        assumption\n      | mult₂ _ hs =>\n        have ⟨δ', hExt, hTy', hStoreTy'⟩ := ih₂ hs rfl\n        exists δ'; constructor\n        assumption; constructor\n        solve_by_elim [store_weakening] using StlcRefTyping\n        assumption\n    | ite0 _ h₂ h₃ ih₁ _ _ =>\n      inversion hEval with\n      | if0Step hs =>\n        have ⟨δ', hExt, hTy', hStoreTy'⟩ := ih₁ hs rfl\n        exists δ'; constructor\n        assumption; constructor\n        constructor <;> solve_by_elim [store_weakening] using StlcRefTyping\n        assumption\n      | if0Zero =>\n        exists δ; constructor\n        apply extends_refl; constructor <;> assumption\n      | if0Nonzero =>\n        exists δ; constructor\n        apply extends_refl; constructor <;> assumption\n    | @ref_ _ _ τ₁ h ih =>\n      inversion hEval with\n      | refValue =>\n        exists δ.concat τ₁; constructor\n        · rw [List.concat_eq_append]; apply extends_app\n        · constructor\n          · have h : <{Ref τ₁}> = <{Ref ~((δ.concat τ₁)[ρ.length])}> := by\n              simp_all [StoreWellTyped, MyGetElem.getElem]\n            rw [h]\n            constructor\n            simp [StoreWellTyped] at hStoreTy ⊢; lia\n          · apply store_well_typed_app <;> assumption\n      | ref_ hs =>\n        have ⟨δ', hExt, hTy', hStoreTy'⟩ := ih hs rfl\n        exists δ'; constructor\n        assumption; constructor\n        solve_by_elim [store_weakening] using StlcRefTyping\n        assumption\n    | deref h ih =>\n      inversion hEval with\n      | derefLoc hl =>\n        inversion h\n        exists δ; constructor\n        apply extends_refl; constructor\n        have ⟨h₁, h₂⟩ := hStoreTy\n        apply h₂ <;> assumption\n        assumption\n      | deref hs =>\n        have ⟨δ', hExt, hTy', hStoreTy'⟩ := ih hs rfl\n        exists δ'; constructor\n        assumption; constructor\n        solve_by_elim [store_weakening] using StlcRefTyping\n        assumption\n    | assign h₁ h₂ ih₁ ih₂ =>\n      inversion hEval with\n      | assign _ hl =>\n        inversion h₁\n        exists δ; constructor\n        apply extends_refl; constructor\n        constructor\n        apply assign_pres_store_typing <;> assumption\n      | assign₁ hs =>\n        have ⟨δ', hExt, hTy', hStoreTy'⟩ := ih₁ hs rfl\n        exists δ'; constructor\n        assumption; constructor\n        solve_by_elim [store_weakening] using StlcRefTyping\n        assumption\n      | assign₂ _ hs =>\n        have ⟨δ', hExt, hTy', hStoreTy'⟩ := ih₂ hs rfl\n        exists δ'; constructor\n        assumption; constructor\n        solve_by_elim [store_weakening] using StlcRefTyping\n        assumption\n\n\n\n\n\n\n","context":"Type Systems\u0009References: Typing Mutable References\u0009Properties\u0009Preservation, Finally","header":"9.5.3.4. Preservation!","id":"/References/#Type-Systems--References___-Typing-Mutable-References--Properties--Preservation___-Finally--Preservation___"}});